#!/bin/bash
# 도입 영상 V3 조립(2026-11-21): Higgsfield Seedance 2.5 1080p 7컷 → 1280x720 크로스페이드, 마지막 컷 4.5초 연장(느린 줌), 36.79초
# 입력 순서(이야기 순서): 태양, 두 신, 개전, 영웅 전투, 어둠 붙잡기, 새벽 영웅, 마을. 자막 시간은 games/autelia/js/prologue/intro_timeline.js
# 사용: 7개 클립을 순서대로 c1.mp4 ~ c7.mp4 로 두고 실행
FG='[0:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v0];[1:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v1];[2:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v2];[3:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v3];[4:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v4];[5:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p[v5];[6:v]scale=1280:720:flags=lanczos,setsar=1,fps=24,format=yuv420p,tpad=stop_mode=clone:stop_duration=4.5,zoompan=z='if(gte(on,121),1+0.00045*(on-121),1)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1280x720:fps=24,format=yuv420p[v6];[v0][v1]xfade=transition=fade:duration=0.5:offset=4.541667[x1];[x1][v2]xfade=transition=fade:duration=0.5:offset=9.083333[x2];[x2][v3]xfade=transition=fade:duration=0.5:offset=13.625[x3];[x3][v4]xfade=transition=fade:duration=0.5:offset=18.166667[x4];[x4][v5]xfade=transition=fade:duration=0.5:offset=22.708333[x5];[x5][v6]xfade=transition=fade:duration=0.5:offset=27.25[x6];[x6]fade=t=in:st=0:d=0.8,fade=t=out:st=35.8:d=1.0,format=yuv420p[out]'
ffmpeg -y -i c1.mp4 -i c2.mp4 -i c3.mp4 -i c4.mp4 -i c5.mp4 -i c6.mp4 -i c7.mp4 -filter_complex "$FG" -map "[out]" -an -c:v libx264 -profile:v baseline -level 3.1 -preset slow -crf 24 -maxrate 2300k -bufsize 4600k -movflags +faststart intro.mp4
ffmpeg -y -i intro.mp4 -an -c:v libvpx-vp9 -b:v 0 -crf 36 -row-mt 1 -deadline good -cpu-used 2 -pix_fmt yuv420p intro.webm
